add_action( 'template_redirect', 'perfectpixel_sku_url_redirect', 5 );

function perfectpixel_sku_url_redirect() {
	if ( ! is_404() ) {
		return;
	}
	$path = trim( (string) wp_parse_url( $_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH ), '/' );
	if ( '' === $path || false !== strpos( $path, '/' ) ) {
		return; // Only single-segment URLs like /SKU123.
	}
	$product_id = wc_get_product_id_by_sku( rawurldecode( $path ) );
	$product    = $product_id ? wc_get_product( $product_id ) : null;
	if ( $product && 'publish' === get_post_status( $product->get_parent_id() ? $product->get_parent_id() : $product->get_id() ) ) {
		wp_safe_redirect( $product->get_permalink(), 301 );
		exit;
	}
}
